using Address = std::uintptr_t;

enum class QtFamily : int { Unknown = 0, Qt5 = 5, Qt6 = 6 };

// One complete ABI layout for a Qt family on one architecture.
struct QtLayout {
    // ---- QObjectData ----
    int obj_qptr;            // q_ptr (must == object address; INVARIANT)
    int obj_parent;          // parent QObject*
    int obj_children;        // children list field
    int obj_children_size;   // sizeof of the children field (8 Qt5 / 24 Qt6)
    int obj_bits;            // bitfield word (isWidget = bit0)
    int obj_posted;
    int obj_metaobj_dyn;
    int obj_sizeof;
    // ---- QObjectPrivate ----
    int priv_extra;          // ExtraData*
    int priv_thread;
    int priv_conn;           // ConnectionData*
    int priv_shared;
    int priv_sizeof;
    // ---- ExtraData ----
    int extra_objectname;      // primary offset of objectName QString
    int extra_objectname_alt;  // alternate build offset (-1 if none)
    // ---- QMetaObject::d ----
    int mo_superdata;        // superdata (SuperData*)
    int mo_stringdata;
    int mo_data;
    int mo_static_metacall;  // StaticMetacallFunction — GOD MODE entry
    int mo_sizeof;
    // ---- QMetaObjectPrivate header ----
    int mop_revision;
    int mop_classname;
    int mop_methodcount;
    int mop_methoddata;
    int mop_signalcount;
    int mop_ints_per_method;  // 5 (Qt5) / 6 (Qt6 rev>=9)
    // ---- Connection graph ----
    int conn_next;           // union next/nextInOrphanList (0)
    int conn_prev;
    int conn_nextlist;
    int conn_sender;
    int conn_receiver;
    int conn_callfn;        // callFunction / slotObj union
    int conn_argtypes;
    int conn_ref;
    int conn_id;
    int conn_moffset;       // ushort method_offset
    int conn_mrelative;     // ushort method_relative
    int conn_bits;          // bitfield word (signal_index:27, ...)
    int conn_sizeof;
    int sv_lists;           // ConnectionList[] offset within SignalVector
    int cd_signalvector;    // signalVector field in ConnectionData
    int cd_sizeof;
    // ---- QString ----
    int str_hdr_size;        // Qt5: size field offset in QArrayData / Qt6: 0
    int str_hdr_offset;     // Qt5: offset field in QArrayData / Qt6: 0
    int str_obj_size;       // sizeof(QString): 8 (Qt5) / 24 (Qt6)
    int str_ptr;            // Qt6: ptr field offset (-1 Qt5)
    int str_size;           // Qt6: size field offset (-1 Qt5)
    // ---- QList ----
    int list_begin;          // Qt5: Data.begin  (-1 Qt6)
    int list_end;           // Qt5: Data.end    (-1 Qt6)
    int list_array;         // Qt5: Data.array  (-1 Qt6)
    int list_ptr;           // Qt6: QADP.ptr    (-1 Qt5)
    int list_size;          // Qt6: QADP.size   (-1 Qt5)
    // ---- QWidget ----
    int qw_data_ptr;        // QWidgetData* member inside QWidget
    int qwd_winid;
    int qwd_flags;
    int qwd_crect;
    int qwd_size;
    // ---- stringdata format ----
    int stringdata_kind;     // 0 = Qt5 (QByteArrayData entries) / 1 = Qt6 (uint pairs)
};

// Version discovery result.
struct QtVersion {
    QtFamily family = QtFamily::Unknown;
    int revision = -1;       // QMetaObjectPrivate::revision (8 = Qt5.12+, 9..12 = Qt6)
    int major = 0, minor = 0, patch = 0;
    std::string module;      // e.g. "Qt6Core.dll" / "libQt5Core.so.5"
    std::string to_string() const;
};

